_status":"published","hours_verified_at":"2026-10-27"},"notes":"Trading hours checked against the operator''s branch page on 2026-10-27. Coordinates mark the shopping centre, not the shop doorway. Service counter hours may differ.","hours":[{"day":"Mon","sort":1,"open":"09:00","close":"19:00","closed":false},{"day":"Tue","sort":2,"open":"09:00","close":"19:00","closed":false},{"day":"Wed","sort":3,"open":"09:00","close":"19:00","closed":false},{"day":"Thu","sort":4,"open":"09:00","close":"19:00","closed":false},{"day":"Fri","sort":5,"open":"09:00","close":"19:00","closed":false},{"day":"Sat","sort":6,"open":"08:30","close":"19:00","closed":false},{"day":"Sun","sort":7,"open":"09:00","close":"17:00","closed":false}]},{"id":"the-fun-company-the-grove","phone":null,"source":"https://thefuncompany.co.za/portfolio_page/the-grove-pretoria/","details":{"shop":"92a","public_and_school_holiday_hours":"10:00-23:00","booking_email":"bookings@thefuncompany.co.za","contact_note":"Operator page lists central booking number 0871649459; centre lists branch 0615616871.","hours_status":"published","hours_verified_at":"2026-10-27"},"notes":"Trading hours checked against the operator''s branch page on 2026-10-27. Coordinates mark the shopping centre, not the shop doorway. Service counter hours may differ.","hours":[{"day":"Mon","sort":1,"open":"11:00","close":"22:00","closed":false},{"day":"Tue","sort":2,"open":"11:00","close":"22:00","closed":false},{"day":"Wed","sort":3,"open":"11:00","close":"22:00","closed":false},{"day":"Thu","sort":4,"open":"11:00","close":"22:00","closed":false},{"day":"Fri","sort":5,"open":"10:00","close":"23:00","closed":false},{"day":"Sat","sort":6,"open":"10:00","close":"23:00","closed":false},{"day":"Sun","sort":7,"open":"10:00","close":"22:00","closed":false}]},{"id":"mtn-the-grove","phone":"0838698173","source":"https://stores.mtn.co.za/mobilephonesanddata-pretoria-equestria","details":{"shop":"19","hours_status":"published","hours_verified_at":"2026-10-27"},"notes":"Trading hours checked against the operator''s branch page on 2026-10-27. Coordinates mark the shopping centre, not the shop doorway. Service counter hours may differ.","hours":[{"day":"Mon","sort":1,"open":"09:00","close":"18:00","closed":false},{"day":"Tue","sort":2,"open":"09:00","close":"18:00","closed":false},{"day":"Wed","sort":3,"open":"09:00","close":"18:00","closed":false},{"day":"Thu","sort":4,"open":"09:00","close":"18:00","closed":false},{"day":"Fri","sort":5,"open":"09:00","close":"18:00","closed":false},{"day":"Sat","sort":6,"open":"09:00","close":"18:00","closed":false},{"day":"Sun","sort":7,"open":"09:00","close":"17:00","closed":false}]}]'::jsonb) AS x(id text,phone text,source text,details jsonb,notes text,hours jsonb)), updated AS(UPDATE public.places p SET phone=coalesce(i.phone,p.phone),source_url=i.source,source_checked_at='2026-10-27',service_details=coalesce(p.service_details,'{}'::jsonb)||i.details,data_notes=coalesce(i.notes,p.data_notes) FROM input i WHERE p.id=i.id RETURNING p.id), hours_updated AS(INSERT INTO public.place_hours(place_id,hours_type,day_of_week,open_time,close_time,is_closed,sort_order,source_url,source_checked_at) SELECT i.id,'opening',h.day,h.open::time,h.close::time,h.closed,h.sort,i.source,'2026-10-27'::date FROM input i CROSS JOIN LATERAL jsonb_to_recordset(i.hours) AS h(day text,sort int,open text,close text,closed boolean) ON CONFLICT(place_id,hours_type,day_of_week) DO UPDATE SET open_time=excluded.open_time,close_time=excluded.close_time,is_closed=excluded.is_closed,sort_order=excluded.sort_order,source_url=excluded.source_url,source_checked_at=excluded.source_checked_at RETURNING place_id) SELECT (SELECT count(*) FROM updated) AS places_updated,(SELECT count(*) FROM hours_updated) AS hours_updated;
